import torch, torch.nn as nn

class LoRA(nn.Module):
    def __init__(self, d, r=8, alpha=16.0):
        super().__init__()
        self.A = nn.Parameter(torch.randn(r, d) * 0.01)
        self.B = nn.Parameter(torch.zeros(d, r))  # B 初始为 0，训练起点等价于原模型
        self.scale = alpha / r

    def forward(self, W0):
        return W0 + self.scale * (self.B @ self.A)  # W0 冻结，不接收梯度

def relay_depth(per_layer_gain, relay_layers):
    # per_layer_gain: 每层能多续传的跳数（示意量）
    # relay_layers: 真正发生接力的中段层索引
    return sum(per_layer_gain[l] for l in relay_layers)

